def separate_legacy_logo_stock(apps, schema_editor):
    """Keep existing logo packs, but stop treating them as a shared SKU pool.

    Rows with a balance are marked artwork_unknown. They are not deleted or
    zeroed. A new empty plain row keeps the catalog code. Packs already
    tied to an order line get an ItemLot so later shipment and corrections
    still move the same row.
    """
    StockItem = apps.get_model("core", "StockItem")
    Item = apps.get_model("core", "Item")
    ItemLot = apps.get_model("core", "ItemLot")
    Variant = apps.get_model("core", "Variant")
    Label = apps.get_model("core", "Label")
    StockCategory = apps.get_model("core", "StockCategory")

    broken = [
        row.pk
        for row in StockItem.objects.all().only("id", "quantity", "reserved")
        if row.quantity < 0 or row.reserved < 0 or row.reserved > row.quantity
    ]
    if broken:
        raise RuntimeError(
            "Stock rows violate quantity >= 0, reserved >= 0 and reserved <= quantity. "
            "Fix them manually before migrating. Ids: "
            + ", ".join(str(pk) for pk in broken)
        )

    from django.core.files.storage import default_storage

    for label in Label.objects.exclude(file=""):
        path = getattr(label.file, "name", label.file)
        try:
            with default_storage.open(path, "rb") as handle:
                label.content_sha256 = hashlib.sha256(handle.read()).hexdigest()
        except (FileNotFoundError, OSError):
            label.content_sha256 = ""
        label.save(update_fields=["content_sha256"])

    category, _ = StockCategory.objects.get_or_create(
        system=True, defaults={"name": "Produkty", "position": 0}
    )
    for stock in StockItem.objects.filter(variant_id__isnull=False).iterator():
        variant = Variant.objects.get(pk=stock.variant_id)
        if not variant.custom_label or (stock.quantity == 0 and stock.reserved == 0):
            continue
        stock.artwork_unknown = True
        stock.code = f"UNK-{stock.pk}"[:40]
        stock.name = (stock.name + " · grafika nieznana")[:180]
        stock.save(update_fields=["artwork_unknown", "code", "name"])
        for item in Item.objects.filter(variant_id=variant.pk, custom_label=True):
            if item.allocated == 0 and item.produced == 0 and item.packed == 0:
                continue
            ItemLot.objects.create(
                item_id=item.pk,
                stock_id=stock.pk,
                allocated=item.allocated,
                produced=item.produced,
                packed=item.packed,
            )

    for variant in Variant.objects.all().iterator():
        if StockItem.objects.filter(
            variant_id=variant.pk, artwork_sha256="", artwork_unknown=False
        ).exists():
            continue
        weight = variant.weight_g
        grams = int(weight) if weight == int(weight) else weight
        base = f"POP-{variant.sku}"[:40]
        code = base
        number = 2
        while StockItem.objects.filter(code=code).exists():
            suffix = f"-{number}"
            code = f"{base[:40 - len(suffix)]}{suffix}"
            number += 1
        StockItem.objects.create(
            code=code,
            name=f"{variant.name} · {grams} g"[:180],
            group="popcorn",
            unit="szt",
            quantity=0,
            reserved=0,
            category=category,
            variant_id=variant.pk,
            artwork_sha256="",
            artwork_unknown=False,
        )


